    "googl-q3": { question: "Avec quelles deux entreprises Google Cloud est-il principalement en concurrence ?", options: ["Amazon Web Services et Microsoft Azure", "Apple et Tesla", "Visa et Mastercard", "Shell et BP"], explanation: "Google Cloud est notamment en concurrence avec AWS et Microsoft Azure." },
