    "nvda-q3": { question: "Что может замедлить спрос на чипы NVIDIA?", options: ["Крупные клиенты сократят расходы на дата-центры", "Ничего", "GPU станут незаконными", "Вырастет цена золота"], explanation: "Расходы крупных клиентов могут замедляться." },
    "nvda-q4": { question: "Что характерно для полупроводниковой отрасли?", options: ["Стабильный спрос", "Циклы высокого спроса и избытка предложения", "Нет конкуренции", "Гарантированный рост"], explanation: "Отрасль исторически проходит циклы дефицита и перепроизводства." },
    "nvda-q5": { question: "Почему акция может упасть после сильного роста?", options: ["Рост всегда гарантирует повышение", "Рост может лишь соответствовать уже высоким ожиданиям", "Рост не связан с ценой", "Акции реагируют только на убытки"], explanation: "При высоких ожиданиях простого соответствия прогнозу может быть недостаточно." },
    "nvda-q6": { question: "От чего зависит большая часть оценки быстрорастущей компании?", options: ["Только от прошлых результатов", "От ожиданий будущего роста", "От офисов", "Ни от чего"], explanation: "В оценке growth-компаний большую роль играют ожидания будущего." },
