export function getLocalizedAssetLearningPath(path: AssetLearningPath, locale: Locale): AssetLearningPath {
  if (locale === "en") return path;
  const patch = (locale === "fr" ? FR : RU)[path.assetId];
  if (!patch) return path;
  return { ...path, title: patch.title, shortDescription: patch.shortDescription,
    lessons: path.lessons.map((l) => patch.lessons[l.id] ? { ...l, ...patch.lessons[l.id] } : l),
    quizQuestions: path.quizQuestions.map((q) => patch.quizQuestions[q.id] ? { ...q, ...patch.quizQuestions[q.id] } : q) };
}

