export function getLocalizedUnlockText(assetId: string, locale: Locale) {
  if (locale === "en") return undefined;
  return (locale === "fr" ? UNLOCK_FR : UNLOCK_RU)[assetId];
}
export function getLocalizedAchievementText(id: string, locale: Locale) {
  if (locale === "en") return undefined;
  return (locale === "fr" ? ACH_FR : ACH_RU)[id];
}
